                default: value.AdditionalProperties[property.Name] = EChartsValue.FromJson(field); break;
            }
        }
        return value;
    }
    internal static bool MatchesWordCloudImageBackground(JsonElement json) => json.ValueKind == JsonValueKind.Object && (!json.TryGetProperty("image", out var pImage) || pImage.ValueKind == JsonValueKind.Null || (WordCloudImage.Matches(pImage)));
    private static void WriteWordCloudImageBackground(Utf8JsonWriter writer, WordCloudImageBackground value, EChartsSerializationContext context, string path)
    {
        context.WriteProperty(writer, value, "image", value.Image, path);
    }
    internal static WordCloudImageBackground ReadWordCloudImageBackground(JsonElement json, EChartsSerializationContext context)
    {
        if (json.ValueKind != JsonValueKind.Object) throw new JsonException("Expected WordCloudImageBackground object.");
        var value = new WordCloudImageBackground();
        foreach (var property in json.EnumerateObject())
        {
            var field = property.Value;
            switch (property.Name)
            {
                case "image":
                    if (field.ValueKind != JsonValueKind.Null && !(WordCloudImage.Matches(field))) throw new JsonException("Invalid WordCloudImageBackground.image.");
                    value.Image = field.ValueKind == JsonValueKind.Null ? (WordCloudImage?)null : WordCloudImage.Read(field); break;
                default: value.AdditionalProperties[property.Name] = EChartsValue.FromJson(field); break;
            }
        }
        return value;
    }
}

/// <summary>Reads core unions through their public reader contract.</summary>
internal static class CoreValues
{
    internal static bool Matches<T>(JsonElement json) where T : struct, IReadableOptionValue<T> => T.Matches(json);
    internal static T Read<T>(JsonElement json) where T : struct, IReadableOptionValue<T> => T.Read(json);
}
